        <div v-if="data.facet_options?.conversion_label?.length" class="kr-check-line"><span>转化效果 <KeywordMetricHelp metric="conversion_label" /></span><el-checkbox-group v-model="draft.conversion_label"><el-checkbox v-for="value in data.facet_options.conversion_label" :key="value" :value="value">{{ value }}</el-checkbox></el-checkbox-group></div>
        <div class="kr-range-grid"><div v-for="metric in reverseMetrics" :key="metric.key" class="kr-range"><label>{{ metric.label }}<small v-if="metric.type==='ratio'"> %</small><KeywordMetricHelp :metric="metric.key" /></label><div><el-input v-model="draft.ranges[metric.key].min" placeholder="最小值" :aria-label="`${metric.label}最小值`" size="small" :inputmode="metric.key==='word_count'?'numeric':'decimal'" /><span>~</span><el-input v-model="draft.ranges[metric.key].max" placeholder="最大值" :aria-label="`${metric.label}最大值`" size="small" :inputmode="metric.key==='word_count'?'numeric':'decimal'" /></div></div></div>
        <div class="kr-keyword-inputs">
