        <el-table ref="table" :data="data.list || []" v-loading="loading" row-key="id" class="kr-table" :height="tableHeight" @selection-change="rows=>selectedRows=rows">
          <el-table-column type="selection" width="32" fixed="left" /><el-table-column type="index" label="#" width="32" fixed="left" :index="index=>(page-1)*pageSize+index+1" />
          <el-table-column label="关键词" prop="keyword" fixed="left" min-width="168"><template #header><button class="kr-sort-button" type="button" aria-label="按关键词排序" @click="setSort('keyword')">关键词 <span>{{ sort==='keyword'?(direction==='asc'?'↑':'↓'):'↕' }}</span></button></template><template #default="{row}"><div class="kr-keyword"><strong>{{ row.keyword }}</strong><span :title="translationTip(row)" :class="{'kr-translated':!!row.translation}">{{ translationStatus(row) }}</span><el-tag v-if="row.keyword_type" size="small" effect="plain">{{ reverseLabel(row.keyword_type) }}</el-tag><el-tag v-if="row.conversion_label" size="small" type="success">{{ row.conversion_label }}</el-tag></div></template></el-table-column>
          <el-table-column v-for="column in tableColumns" :key="column.key" :label="column.label" :min-width="column.width" :align="['distribution','asins'].includes(column.key)?'left':'center'" :class-name="`kr-col-${column.key}`">
            <template #header>
              <div class="kr-group-header">
                <span v-if="column.key==='concentration'" class="kr-concentration-title">ABA集中度</span>
                <template v-if="column.fields.length"><div v-for="field in column.fields" :key="field.key" class="kr-header-metric"><button type="button" class="kr-sort-button" :class="{'kr-sort-active':sort===field.key}" :aria-label="`按${field.label}排序`" :title="`按${field.label}排序；${column.label}`" @click="setSort(field.key)">{{ field.label }} <span>{{ sort===field.key?(direction==='asc'?'↑':'↓'):'↕' }}</span></button><KeywordMetricHelp :metric="field.key" /></div></template>
                <div v-else class="kr-header-metric"><span>{{ column.label }}</span><KeywordMetricHelp :metric="column.key==='distribution'?'traffic_type':column.key" /></div>
                <small v-if="['organic','sponsored'].includes(column.key)">快照排名，非实时</small>
              </div>
            </template>
            <template #default="{row}">
              <div v-if="column.key==='flow'"><strong class="kr-traffic-number">{{ valueOf('traffic_share',row.traffic_share) }}</strong><small :title="'预估周曝光量'">周曝光 {{ valueOf('weekly_impressions',row.weekly_impressions) }}</small></div>
              <div v-else-if="column.key==='distribution'" class="kr-distribution"><span>{{ reverseLabel(row.traffic_type) || '—' }}</span><div>自然 <b>{{ valueOf('organic_share',row.organic_share) }}</b></div><div class="kr-bar"><span :style="{width:percentWidth(row.organic_share)+'%'}" /></div><div>广告 <b class="kr-blue">{{ valueOf('sponsored_share',row.sponsored_share) }}</b></div><div class="kr-bar kr-bar-blue"><span :style="{width:percentWidth(row.sponsored_share)+'%'}" /></div></div>
              <div v-else-if="['organic','sponsored'].includes(column.key)" class="kr-rank" :class="{'kr-rank-ad':column.key==='sponsored'}"><template v-if="hasValue(row[column.key+'_rank'])"><strong>{{ valueOf(column.key+'_rank',row[column.key+'_rank']) }}</strong><span v-if="rankPageText(row[column.key+'_page'])" :title="row[column.key+'_page']">{{ rankPageText(row[column.key+'_page']) }}</span><el-tooltip :content="'导出快照的来源更新时间：'+(row[column.key+'_updated_text'] || '未提供，不能当作今日排名')" placement="top"><small class="kr-rank-time">{{ row[column.key+'_updated_text'] || '更新时间未提供' }}</small></el-tooltip></template><span v-else class="kr-rank-missing" title="未记录具体排名时采用此展示文案，非实时查询结果">前3页无排名</span></div>
              <div v-else-if="column.key==='monthly_searches'" class="kr-number">{{ valueOf('monthly_searches',row.monthly_searches) }}<small :class="growthClass(row.search_growth_mom)" title="搜索量环比">{{ hasValue(row.search_growth_mom)?(Number(row.search_growth_mom)>0?'+':'')+valueOf('search_growth_mom',row.search_growth_mom):'—' }}</small></div>
              <div v-else-if="column.key==='bid'" class="kr-bid-stack"><small title="建议竞价下限">{{ valueOf('suggested_bid_min',row.suggested_bid_min) }}</small><strong title="PPC竞价（导出值）">{{ valueOf('ppc',row.ppc) }}</strong><small title="建议竞价上限">{{ valueOf('suggested_bid_max',row.suggested_bid_max) }}</small></div>
              <div v-else-if="column.key==='trend'" class="kr-muted">—</div>
              <template v-else-if="column.key==='asins'"><el-popover v-if="validAsins(row.top_asins).length" trigger="click" :width="230"><template #reference><el-button link type="primary">查看 {{ validAsins(row.top_asins).length }} 个</el-button></template><div class="kr-competing-asins"><span v-for="asin in validAsins(row.top_asins)" :key="asin">{{ asin }}</span></div></el-popover><span v-else>—</span></template>
              <div v-else class="kr-stacked-metrics"><span v-for="field in column.fields" :key="field.key" :data-metric="field.key" :title="field.label" :class="{'kr-secondary-metric':column.key==='concentration' && field.key==='total_conversion_share'}">{{ valueOf(field.key,row[field.key]) }}</span></div>
            </template>
          </el-table-column>
          <el-table-column width="40" fixed="right" align="center"><template #default="{row}"><el-tooltip content="复制关键词"><el-button link type="primary" :icon="CopyDocument" :aria-label="`复制关键词 ${row.keyword}`" @click="copyText(row.keyword)" /></el-tooltip></template></el-table-column>
          <template #empty>{{ error?'读取失败，请重读本地数据':data.snapshot?'没有符合筛选条件的关键词':'该ASIN暂无已清洗快照，请先配置并等待采集任务导入' }}</template>
        </el-table>
        <div class="kr-pagination"><span>共 {{ data.total ?? 0 }} 个关键词 · 当前 {{ tableColumns.length }} 组指标 · 表格内滚动翻看，更多指标可在自定义列中启用</span><el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20,50,100]" :total="data.total || 0" layout="total, sizes, prev, pager, next, jumper" :disabled="loading" @current-change="load" @size-change="resizePage" /></div>
      </section>
      <el-drawer v-model="columnsOpen" title="自定义关键词列" size="min(440px, 96vw)" append-to-body><div class="kr-column-settings"><p>关键词和选择列始终固定。勾选显示指标，拖动行或用箭头调整顺序；合并列中的上下指标可分别点击表头排序。</p><div class="kr-column-presets"><el-button size="small" @click="columnPreset('common')">常用列</el-button><el-button size="small" @click="columnPreset('all')">全部显示</el-button><el-button size="small" @click="columnPreset('none')">清空可选列</el-button></div><div v-for="(column,index) in orderedColumns" :key="column.key" class="kr-column-setting-row" draggable="true" @dragstart="startColumnDrag($event,column.key)" @dragover.prevent @drop.prevent="dropColumn(column.key)" @dragend="dragColumn=null"><span class="kr-column-grip" title="拖动调整顺序">⠿</span><el-checkbox :model-value="visibleColumns.includes(column.key)" @change="value=>toggleColumn(column.key,value)">{{ column.label }}</el-checkbox><div><el-button link :icon="ArrowUp" :disabled="index===0" :aria-label="`上移${column.label}`" @click="moveColumn(column.key,-1)" /><el-button link :icon="ArrowDown" :disabled="index===orderedColumns.length-1" :aria-label="`下移${column.label}`" @click="moveColumn(column.key,1)" /></div></div><div class="kr-column-save-note">{{ prefsUnavailable?'浏览器存储不可用，列设置仅本次有效。':'列设置自动保存在当前浏览器，刷新和切换ASIN后仍保留。' }}</div></div></el-drawer>
    </template>
    <section v-else class="kr-welcome kr-panel"><el-icon><Search /></el-icon><h2>输入ASIN，查看已导入的关键词数据</h2><p>支持本店商品和竞品ASIN，也可以从上方店铺列表中选择商品。</p></section>
  </main>
</template>
<script>export default {name:'KeywordReverseView'}</script>
<script setup>
import { computed, nextTick, onActivated, onBeforeUnmount, onDeactivated, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElMessage } from 'element-plus'
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUp, CopyDocument, Download, Filter, Refresh, RefreshLeft, Search, Setting } from '@element-plus/icons-vue'
import { getKeywordReverse, getKeywordReverseOptions } from '@/services/api'
import { spriteStates, spriteTime, spriteValue } from '@/utils/sellersprite'
import { reverseMetrics, reverseLabel, hasValue, percentWidth, reverseCsv, reverseColumns, defaultColumnPrefs, normalizeColumnPrefs, rankPageText } from '@/utils/keywordReverse'
import KeywordMetricHelp from '@/components/KeywordMetricHelp.vue'
import { translationStatus, translationTip } from '@/utils/translationStatus'

const route=useRoute(),router=useRouter(),table=ref(null)
const data=ref({}),error=ref(''),loading=ref(false),asinInput=ref(''),activeAsin=ref(''),shopId=ref(''),pickedAsin=ref(''),snapshotId=ref(''),page=ref(1),pageSize=ref(50)
const options=ref([]),shops=ref([]),optionsLoading=ref(false),optionsMore=ref(false),optionsError=ref(''),expandWords=ref(false),selectedRows=ref([])
const blankFilters=()=>({ranges:Object.fromEntries(reverseMetrics.map(m=>[m.key,{min:'',max:''}])),traffic_type:[],conversion_label:[],include:'',exclude:'',include_match:'broad'})
const draft=reactive(blankFilters()),applied=ref(blankFilters()),sort=ref('traffic_share'),direction=ref('desc')
const preferenceKey='erp.keywordReverse.columns.v1',prefsUnavailable=ref(false),columnsOpen=ref(false),dragColumn=ref(null)
let initialPrefs
try{initialPrefs=normalizeColumnPrefs(JSON.parse(localStorage.getItem(preferenceKey) || 'null'))}catch{initialPrefs=defaultColumnPrefs();prefsUnavailable.value=true}
const columnOrder=ref(initialPrefs.order),visibleColumns=ref(initialPrefs.visible)
const orderedColumns=computed(()=>columnOrder.value.map(key=>reverseColumns.find(c=>c.key===key)).filter(Boolean))
const tableColumns=computed(()=>orderedColumns.value.filter(c=>visibleColumns.value.includes(c.key)))
const tableHeight=ref(Math.max(320,Math.min(640,window.innerHeight-270))),scrollTrack=ref(null),scrollState=reactive({left:0,width:0,view:0})
const horizontalOverflow=computed(()=>scrollState.width>scrollState.view+2)
const shownWords=computed(()=>(data.value.word_frequency || []).filter(w=>Array.isArray(w) && w.length).slice(0,expandWords.value?100:25))
const valueOf=(key,value)=>spriteValue(reverseMetrics.find(m=>m.key===key) || {type:'text'},value)
const growthClass=value=>hasValue(value)?Number(value)>0?'kr-positive':Number(value)<0?'kr-negative':'':''
const validAsins=values=>Array.isArray(values)?values.filter(v=>/^[A-Z0-9]{10}$/.test(v)):[]
let disposed=false,active=true,revision=0,optionsRevision=0,optionsPage=1,optionsSearch='',timer=null,lastRouteKey=''
let optionsLoadedKey='',optionsRequestKey=''
let boundBody=null,tableObserver=null,measureFrame=null

function columnPreset(preset){const defaults=defaultColumnPrefs();columnOrder.value=defaults.order;visibleColumns.value=preset==='all'?defaults.order:preset==='none'?[]:defaults.visible}
function toggleColumn(key,value){visibleColumns.value=value?[...new Set([...visibleColumns.value,key])]:visibleColumns.value.filter(item=>item!==key)}
function moveColumn(key,offset){const items=[...columnOrder.value],index=items.indexOf(key),target=index+offset;if(index<0 || target<0 || target>=items.length)return;items.splice(index,1);items.splice(target,0,key);columnOrder.value=items}
function startColumnDrag(event,key){dragColumn.value=key;if(event.dataTransfer){event.dataTransfer.effectAllowed='move';event.dataTransfer.setData('text/plain',key)}}
function dropColumn(key){if(!dragColumn.value || dragColumn.value===key)return;const items=[...columnOrder.value],from=items.indexOf(dragColumn.value),to=items.indexOf(key);if(from>=0 && to>=0){items.splice(from,1);items.splice(to,0,dragColumn.value);columnOrder.value=items}dragColumn.value=null}
function syncTrack(){const track=scrollTrack.value,range=scrollState.width-scrollState.view;if(!track || range<=0)return;const left=scrollState.left/range*(track.scrollWidth-track.clientWidth);if(Math.abs(track.scrollLeft-left)>1)track.scrollLeft=left}
function bodyScrolled(){if(!boundBody)return;scrollState.left=boundBody.scrollLeft;syncTrack()}
function trackScroll(){const track=scrollTrack.value;if(!boundBody || !track || track.scrollWidth<=track.clientWidth)return;const left=track.scrollLeft/(track.scrollWidth-track.clientWidth)*(scrollState.width-scrollState.view);if(Math.abs(boundBody.scrollLeft-left)>1)boundBody.scrollLeft=left}
function scrollTable(direction){if(boundBody)boundBody.scrollBy({left:direction*Math.max(180,boundBody.clientWidth*.6),behavior:'smooth'})}
function measureScroll(){if(measureFrame!==null)cancelAnimationFrame(measureFrame);measureFrame=requestAnimationFrame(()=>{measureFrame=null;if(!active || disposed || !boundBody)return;scrollState.width=boundBody.scrollWidth;scrollState.view=boundBody.clientWidth;scrollState.left=boundBody.scrollLeft;nextTick(syncTrack)})}
function disconnectScroller(){if(measureFrame!==null)cancelAnimationFrame(measureFrame);measureFrame=null;tableObserver?.disconnect();tableObserver=null;boundBody?.removeEventListener('scroll',bodyScrolled);boundBody=null}
async function connectScroller(){await nextTick();if(!active || disposed)return;table.value?.doLayout();const body=table.value?.$el.querySelector('.el-table__body-wrapper .el-scrollbar__wrap');if(body!==boundBody){disconnectScroller();boundBody=body || null;if(boundBody){boundBody.addEventListener('scroll',bodyScrolled,{passive:true});if(typeof ResizeObserver!=='undefined'){tableObserver=new ResizeObserver(measureScroll);tableObserver.observe(boundBody);const inner=boundBody.querySelector('.el-table__body');if(inner)tableObserver.observe(inner)}}}measureScroll()}
function resizeTable(){tableHeight.value=Math.max(320,Math.min(640,window.innerHeight-270));connectScroller()}
watch([columnOrder,visibleColumns],()=>{try{localStorage.setItem(preferenceKey,JSON.stringify({version:1,order:columnOrder.value,visible:visibleColumns.value}));prefsUnavailable.value=false}catch{prefsUnavailable.value=true}connectScroller()},{deep:true})
watch([activeAsin,()=>data.value.list,()=>tableColumns.value.map(c=>c.key).join(',')],connectScroller,{flush:'post'})
watch(scrollTrack,()=>nextTick(syncTrack))

async function load(){
  if(!activeAsin.value || !active || disposed)return
  const request=++revision;loading.value=true;error.value='';selectedRows.value=[];table.value?.clearSelection()
  const ranges=Object.fromEntries(Object.entries(applied.value.ranges).filter(([,b])=>b.min!=='' || b.max!==''))
  try{
    const res=await getKeywordReverse(activeAsin.value,{task_id:snapshotId.value || undefined,page:page.value,page_size:pageSize.value,sort:sort.value,direction:direction.value,ranges:JSON.stringify(ranges),traffic_type:JSON.stringify(applied.value.traffic_type),conversion_label:JSON.stringify(applied.value.conversion_label),include:applied.value.include,exclude:applied.value.exclude,include_match:applied.value.include_match})
    if(disposed || !active || request!==revision)return
    data.value=res.data.data;snapshotId.value=data.value.snapshot?.id || ''
  }catch(err){if(!disposed && active && request===revision){data.value={};error.value=err.response?.data?.message || '读取失败，请重读本地数据'}}finally{if(!disposed && active && request===revision)loading.value=false}
}
function syncRoute(){
  if(route.path!=='/tools/keyword-reverse' || disposed)return
  active=true
  const asin=String(route.query.asin || '').trim().toUpperCase(),task=String(route.query.task_id || ''),routeShop=String(route.query.shop_id || ''),key=asin+':'+task+':'+routeShop
  if(key===lastRouteKey)return
  lastRouteKey=key
  const changed=asin!==activeAsin.value;asinInput.value=asin;shopId.value=/^\d+$/.test(String(route.query.shop_id || ''))?String(route.query.shop_id):'';pickedAsin.value=''
  revision++;data.value={};error.value='';loading.value=false
  if(!asin){activeAsin.value='';return}
  if(!/^[A-Z0-9]{10}$/.test(asin)){activeAsin.value='';error.value='请输入10位英文字母或数字组成的ASIN';return}
  activeAsin.value=asin;snapshotId.value=task;page.value=1
  if(changed){Object.assign(draft,blankFilters());applied.value=blankFilters();expandWords.value=false}
  load();loadOptions()
}
function openAsin(){const asin=asinInput.value.trim().toUpperCase();if(!/^[A-Z0-9]{10}$/.test(asin)){ElMessage.warning('请输入10位英文字母或数字组成的ASIN');return}if(route.query.asin===asin && !route.query.task_id && String(route.query.shop_id || '')===shopId.value){snapshotId.value='';page.value=1;load();return}router.push({path:'/tools/keyword-reverse',query:{asin,shop_id:shopId.value || undefined}})}
function selectAsin(value){if(value){asinInput.value=value;openAsin()}}
function changeShop(){pickedAsin.value='';optionsSearch='';loadOptions()}
function optionsKey(){return shopId.value+':'+optionsSearch}
function searchOptions(query){
  const value=String(query || '')
  // 展开会回调过滤函数；相同条件不清空选项、不重复请求，避免下拉反复弹出。
  if(value===optionsSearch && (optionsLoadedKey===optionsKey() || optionsLoading.value))return
  optionsSearch=value;optionsRevision++;optionsRequestKey='';clearTimeout(timer)
  timer=setTimeout(()=>{timer=null;loadOptions()},300)
}
async function loadOptions(append=false){
  if(disposed || !active)return
  clearTimeout(timer);timer=null
  const key=optionsKey()
  if(!append && ((optionsLoadedKey===key && !optionsLoading.value && !optionsError.value) || (optionsRequestKey===key && optionsLoading.value)))return
  if(append && optionsLoadedKey!==key)return
  // 保留现有选项直到新响应到达；普通选择框在加载/空结果时也保持单次展开。
  if(!append)optionsPage=1
  const request=++optionsRevision,requestedPage=append?optionsPage+1:1;optionsLoading.value=true;optionsError.value=''
  optionsRequestKey=key
  try{const res=await getKeywordReverseOptions({shop_id:shopId.value || undefined,search:optionsSearch,page:requestedPage});if(disposed || !active || request!==optionsRevision)return;shops.value=res.data.data.shops;options.value=append?[...options.value,...res.data.data.list]:res.data.data.list;optionsMore.value=res.data.data.has_more;optionsPage=requestedPage;optionsLoadedKey=key}catch(err){if(!disposed && active && request===optionsRevision){optionsError.value=err.response?.data?.message || '店铺ASIN读取失败，请重新选择店铺';options.value=[];optionsLoadedKey='';optionsMore.value=false}}finally{if(!disposed && active && request===optionsRevision)optionsLoading.value=false}
}
function loadMoreOptions(){if(optionsLoading.value || timer)return;loadOptions(true)}
function applyFilters(){applied.value=JSON.parse(JSON.stringify(draft));page.value=1;load()}
function resetFilters(){Object.assign(draft,blankFilters());applyFilters()}
function useWord(word){draft.include=String(word);applyFilters()}
function setSort(key){direction.value=sort.value===key && direction.value==='desc'?'asc':'desc';sort.value=key;page.value=1;load()}
function resizePage(){page.value=1;load()}
function changeSnapshot(){router.push({path:'/tools/keyword-reverse',query:{asin:activeAsin.value,shop_id:shopId.value || undefined,task_id:snapshotId.value || undefined}})}
function latestSnapshot(){if(!route.query.task_id){snapshotId.value='';page.value=1;load()}else router.push({path:'/tools/keyword-reverse',query:{asin:activeAsin.value,shop_id:shopId.value || undefined}})}
async function copyText(text){try{await navigator.clipboard.writeText(text);ElMessage.success('已复制')}catch{ElMessage.warning('复制失败，请手动复制')}}
function copyWords(){copyText((selectedRows.value.length?selectedRows.value:data.value.list || []).map(row=>row.keyword).join('\n'))}
function exportPage(){const columns=data.value.columns || [],rows=data.value.list || [],url=URL.createObjectURL(new Blob([reverseCsv(rows,columns)],{type:'text/csv;charset=utf-8;'})),link=document.createElement('a');link.href=url;link.download=`${activeAsin.value}_${data.value.snapshot?.record_date || 'snapshot'}_第${page.value}页.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
watch(()=>[route.path,route.query.asin,route.query.task_id,route.query.shop_id],syncRoute,{immediate:true})
onMounted(()=>{window.addEventListener('resize',resizeTable);resizeTable()})
onActivated(()=>{active=true;window.addEventListener('resize',resizeTable);syncRoute();resizeTable();if(!shops.value.length && !optionsLoading.value)loadOptions()})
onDeactivated(()=>{active=false;revision++;optionsRevision++;loading.value=false;optionsLoading.value=false;lastRouteKey='';columnsOpen.value=false;clearTimeout(timer);disconnectScroller();window.removeEventListener('resize',resizeTable)})
onBeforeUnmount(()=>{disposed=true;active=false;revision++;optionsRevision++;clearTimeout(timer);disconnectScroller();window.removeEventListener('resize',resizeTable)})
nextTick(()=>{if(!activeAsin.value)loadOptions()})
</script>
